package io.github.rebrowser.permissions;
import org.junit.Test;
import static org.junit.Assert.*;
import io.github.rebrowser.bootstrap.*;
import java.util.concurrent.atomic.*;
/** Actual native negative-only coordinator with synthetic SDK callbacks/clock/source, NO grants. */
public final class PermissionCoordinatorTest {
 static final class F {final AtomicLong clock=new AtomicLong(100);final AtomicReference<ComponentGate.SourceView> source=new AtomicReference<>(ComponentGate.SourceView.acceptedNative(this,new byte[16]));final ComponentGate gate=ComponentGate.forNativeSource(ProcessRole.MAIN,source::get);final PermissionCoordinator coordinator=new PermissionCoordinator(gate.captureDataEpoch(gate.requireBusiness()),clock::get);final Object session=new Object(),document=new Object(),partition=new Object();final AtomicInteger denied=new AtomicInteger(),allowed=new AtomicInteger();PermissionCoordinator.Request offer(){return offer(allow->{if(allow)allowed.incrementAndGet();else denied.incrementAndGet();});}PermissionCoordinator.Request offer(PendingPromptRegistry.Completion c){return coordinator.offerActualSdkRequest(new Object(),session,document,1,partition,"https://example.test/path",SiteGrantStore.Capability.CAMERA,(s,d,g)->{if(s!=session || d!=document || g!=1)throw new SecurityException();},c);}}
 @Test public void allowIntentCannotBecomePermanentOrFiniteGeckoGrant(){F f=new F();PermissionCoordinator.Request r=f.offer();assertEquals(PermissionCoordinator.ChoiceOutcome.ALLOW_INTENT_RECORDED_FINITE_NATIVE_GRANT_UNAVAILABLE,f.coordinator.chooseFromNativeWindow(r,SiteGrantStore.Choice.ALLOW_ONCE_INTENT));assertEquals(0,f.allowed.get());assertEquals(1,f.denied.get());assertEquals(PermissionCoordinator.State.DENIAL_CALLBACK_RETURNED,r.state());}
 @Test public void denyExactlyOnceAndNoFreshLatestRequest(){F f=new F();PermissionCoordinator.Request r=f.offer();f.coordinator.chooseFromNativeWindow(r,SiteGrantStore.Choice.DENY);assertThrows(SecurityException.class,()->f.coordinator.chooseFromNativeWindow(r,SiteGrantStore.Choice.DENY));assertEquals(1,f.denied.get());}
 @Test public void originIsNormalizedRoutingHintOnly(){F f=new F();PermissionCoordinator.Request r=f.offer();assertEquals("https://example.test",r.candidateOriginForNativeDisplay());assertNull(f.coordinator.currentDecisionHint(r));}
 @Test public void rememberedAllowRemainsHintOnFutureSdkRequest(){F f=new F();f.coordinator.chooseFromNativeWindow(f.offer(),SiteGrantStore.Choice.ALLOW_ONCE_INTENT);PermissionCoordinator.Request later=f.offer();assertEquals(SiteGrantStore.Choice.ALLOW_ONCE_INTENT,f.coordinator.currentDecisionHint(later).rememberedChoice());assertEquals(0,f.allowed.get());}
 @Test public void exactDeadlineExpiresAndRequestsDenial(){F f=new F();PermissionCoordinator.Request r=f.offer();f.clock.addAndGet(30000);assertThrows(SecurityException.class,()->f.coordinator.chooseFromNativeWindow(r,SiteGrantStore.Choice.ALLOW_ONCE_INTENT));f.coordinator.expireOwnedPrompts();assertEquals(1,f.denied.get());}
 @Test public void wrongDocumentCannotRetargetOldPrompt(){F f=new F();PermissionCoordinator.Request r=f.offer();f.coordinator.retireNativeDocument(f.session,new Object());assertEquals(0,f.denied.get());f.coordinator.retireNativeDocument(f.session,f.document);assertEquals(1,f.denied.get());assertThrows(SecurityException.class,()->f.coordinator.chooseFromNativeWindow(r,SiteGrantStore.Choice.DENY));}
 @Test public void sourceLockStillAllowsOldNativeDenialSettlement(){F f=new F();f.offer();f.source.set(ComponentGate.SourceView.untrusted(ComponentGate.SourceState.LOCKED));f.coordinator.retireAll();assertEquals(1,f.denied.get());assertEquals(0,f.allowed.get());}
 @Test public void unknownCallbackDoesNotSkipOtherIndependentDenials(){F f=new F();PermissionCoordinator.Request bad=f.offer(allow->{throw new IllegalStateException("synthetic unknown");});f.offer();assertThrows(IllegalStateException.class,f.coordinator::retireAll);assertEquals(PermissionCoordinator.State.DENIAL_CALLBACK_UNKNOWN,bad.state());assertEquals(1,f.denied.get());f.coordinator.retireAll();assertEquals(1,f.denied.get());}
 @Test public void callbackReentryDoesNotAnswerSameRequestTwice(){F f=new F();AtomicInteger calls=new AtomicInteger();f.offer(allow->{calls.incrementAndGet();f.coordinator.retireAll();});f.coordinator.retireAll();assertEquals(1,calls.get());}
 @Test public void ownerThreadOnlyAndClockRollbackSticky()throws Exception{F f=new F();PermissionCoordinator.Request r=f.offer();AtomicReference<Throwable> error=new AtomicReference<>();Thread t=new Thread(()->{try{f.coordinator.chooseFromNativeWindow(r,SiteGrantStore.Choice.DENY);}catch(Throwable e){error.set(e);}});t.start();t.join();assertTrue(error.get() instanceof IllegalStateException);f.clock.set(99);assertThrows(SecurityException.class,f::offer);f.clock.set(100);assertThrows(SecurityException.class,f::offer);}
}
